#include <stdio.h>

int main(void) {
    int la_bits = 32, page_bits = 12, pte_bytes = 4, level_bits = 10;
    int page_size = 1 << page_bits;
    int vpn_bits = la_bits - page_bits;
    long pte_count = 1L << vpn_bits;

    printf("=== given ===\n");
    printf("logical address bits = %d, page size = %d B, PTE = %d B\n", la_bits, page_size, pte_bytes);
    printf("=== derived ===\n");
    printf("page offset bits   = log2(%d) = %d\n", page_size, page_bits);
    printf("page number bits   = %d - %d = %d\n", la_bits, page_bits, vpn_bits);
    printf("number of PTEs     = 2^%d = %ld\n", vpn_bits, pte_count);
    printf("single-level PT    = %ld * %d B = %ld B = %ld KB\n",
           pte_count, pte_bytes, pte_count * pte_bytes, pte_count * pte_bytes / 1024);

    printf("=== two-level ===\n");
    printf("split VPN into L1(%d bits) + L2(%d bits)\n", level_bits, level_bits);
    long l1 = 1L << level_bits;
    printf("page directory     = 2^%d = %ld entries = %ld B (= 1 page)\n", level_bits, l1, l1 * pte_bytes);
    printf("each L2 table      = 2^%d = %ld entries = %ld B\n", level_bits, l1, l1 * pte_bytes);
    printf("if a process uses k L2 tables, resident PT = %ld B + k*%ld B\n", l1 * pte_bytes, l1 * pte_bytes);
    for (int k = 1; k <= 3; k++)
        printf("  k=%d -> %ld B, saved %.4f%% vs single-level\n", k,
               l1 * pte_bytes * (1 + k),
               100.0 * (1.0 - (double)(l1 * pte_bytes * (1 + k)) / (double)(pte_count * pte_bytes)));
    printf("cost: 2 page-table walks + 1 data access = 3 memory accesses without TLB\n");
    return 0;
}
